const GENRES  = ["Action", "Adventure", "Animation", "Comedy", "Crime", "Drama", "Family", "Fantasy", "History", "Horror", "Music", "Mystery", "Romance", "Science Fiction", "Thriller"];
let sel = new Set(), strat = "hybrid";

// Genre chips
const gc = document.getElementById("gchips");
GENRES.forEach(g => {
  const b = document.createElement("button");
  b.className = "g-chip"; b.textContent = g;
  b.onclick = () => { sel.has(g)?sel.delete(g):sel.add(g); b.classList.toggle("on", sel.has(g)); };
  gc.appendChild(b);
});

// Strategy
document.getElementById("sbtn").addEventListener("click", e => {
  const btn = e.target.closest(".strat-btn"); if (!btn) return;
  strat = btn.dataset.s;
  document.querySelectorAll(".strat-btn").forEach(b => b.classList.remove("active"));
  btn.classList.add("active");
});

function cf(id) { let h=(id*2654435761)>>>0; return 0.38+(h%1000)/1000*0.50; }
function ct(m) {
  if(!sel.size) return 0.5;
  const o = m.genres.filter(g=>sel.has(g)).length;
  return Math.min(1, o/sel.size*0.65 + o/m.genres.length*0.35);
}
function score(m, collab) {
  const c=ct(m), p=Math.min(1,Math.log1p(m.pop)/4);
  if(strat==="collaborative") return collab;
  if(strat==="content")       return c;
  if(strat==="popularity")    return p;
  return 0.55*collab + 0.30*c + 0.15*p;
}

function renderDemo() {
  const uid = Math.max(1, Math.min(500, parseInt(document.getElementById("uid").value)||1));
  const key = String(((uid-1)%50)+1);
  const preRecs = RECS[key] || RECS["1"];
  const preMap = {};
  preRecs.forEach(r => { preMap[r.movie_id] = r.collab; });

  document.getElementById("rtitle").textContent = "Recommendations for User #"+uid;
  document.getElementById("rmeta").textContent  = strat+" strategy · top 10";

  const scored = MOVIES.map(m => {
    const collab = preMap[m.id] !== undefined ? preMap[m.id] : cf(m.id);
    const c = ct(m), p = Math.min(1, Math.log1p(m.pop)/4);
    return {...m, score:score(m,collab), collab, ct:c, pop:p};
  }).sort((a,b)=>b.score-a.score).slice(0,10);

  const grid = document.getElementById("rgrid");
  grid.innerHTML = "";
  scored.forEach((m, i) => {
    const cW=Math.round(m.collab*100), ctW=Math.round(m.ct*100), pW=Math.round(m.pop*100);
    const d = document.createElement("div");
    d.className = "r-card"+(i===0?" top":"");
    d.style.animationDelay = (i*0.04)+"s";
    d.innerHTML =
      '<div class="r-rank '+(i===0?"gold":"")+'">#'+(i+1)+'</div>'+
      '<div>'+
        '<div class="r-title">'+m.title+'</div>'+
        '<div class="r-genres">'+m.genres.slice(0,3).map(g=>'<span class="r-genre">'+g+'</span>').join("")+'</div>'+
        '<div class="r-bars">'+
          '<div class="r-bar-row"><div class="r-bar-label">collab</div><div class="r-bar-bg"><div class="r-bar-fill bar-t" style="width:'+cW+'%"></div></div><div class="r-bar-val">'+cW+'%</div></div>'+
          '<div class="r-bar-row"><div class="r-bar-label">content</div><div class="r-bar-bg"><div class="r-bar-fill bar-a" style="width:'+ctW+'%"></div></div><div class="r-bar-val">'+ctW+'%</div></div>'+
          '<div class="r-bar-row"><div class="r-bar-label">popular</div><div class="r-bar-bg"><div class="r-bar-fill bar-b" style="width:'+pW+'%"></div></div><div class="r-bar-val">'+pW+'%</div></div>'+
        '</div>'+
      '</div>'+
      '<div class="r-score-block">'+
        '<div class="r-score">'+(m.score*10).toFixed(2)+'</div>'+
        '<div class="r-score-label">score</div>'+
        '<div class="r-year">'+m.year+' · ★'+m.vote_avg+'</div>'+
      '</div>';
    grid.appendChild(d);
  });
}

// Metric bars
function doMetricBars() {
  document.getElementById("mb1").style.width="94%";
  document.getElementById("mb2").style.width="98%";
  document.getElementById("mb3").style.width="92%";
  document.getElementById("mb4").style.width="80%";
}

// Counter
function counter(id, target, suffix, dur=1600) {
  const el=document.getElementById(id); if(!el) return;
  const s=performance.now();
  function tick(now) {
    const t=Math.min((now-s)/dur,1), e=1-Math.pow(1-t,3);
    el.innerHTML=Math.round(target*e)+'<span style="color:var(--teal);font-size:22px">'+suffix+'</span>';
    if(t<1) requestAnimationFrame(tick);
  }
  requestAnimationFrame(tick);
}

// Scroll reveal
const io = new IntersectionObserver(entries => {
  entries.forEach(e => {
    if(e.isIntersecting) {
      e.target.classList.add("in");
      if(e.target.closest("#metrics")) doMetricBars();
    }
  });
}, {threshold:0.12});
document.querySelectorAll(".reveal").forEach(el=>io.observe(el));

window.addEventListener("load", ()=>{
  renderDemo();
  setTimeout(()=>{
    counter("s1",1,"M+");
    counter("s2",100,"ms");
    counter("s3",94,"%");
    counter("s4",80,"%");
  }, 500);
});

document.getElementById("uid").addEventListener("keydown", e=>{ if(e.key==="Enter") renderDemo(); });